  /** Walk the hierarchy to gather coercions. */
  override def walk(node: Any) = node match {

    // Lift out this trait's coercions.
    case t @ STraitDecl(t1, STraitTypeHeader(h1, h2, h3, h4, h5, h6, h7, h8, _), t3, t4, t5, t6) =>
